<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/credits.php';$current=tuman_require_role('TEACHER');$db=tuman_database();$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$credit=$id?tuman_teacher_credit($db,$current['id'],(int)$id):null;if(!$credit||$credit['status']!=='ACTIVE'){http_response_code(404);exit('Credit unavailable.');}$invoices=array_filter(tuman_teacher_payment_invoices($db,$current['id'],true),fn($i)=>$i['teacher_student_id']==$credit['teacher_student_id']&&$i['currency_code']===$credit['currency_code']);$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$invoiceId=filter_var($_POST['invoice_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$invoiceId)throw new InvalidArgumentException('Choose an invoice.');tuman_apply_credit($db,$current['id'],(int)$id,(int)$invoiceId,(string)($_POST['amount']??''));header('Location: /Tuman/teacher/credits.php');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}}tuman_teacher_page_start('Apply credit');?><h1>Apply credit</h1><p>Available: <?=htmlspecialchars(tuman_invoice_money_label($credit['remaining_amount'],$credit['currency_code']),ENT_QUOTES,'UTF-8')?> for <?=htmlspecialchars(trim($credit['first_name'].' '.($credit['last_name']??'')),ENT_QUOTES,'UTF-8')?>.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=$id?>"><p><label>Invoice <select name="invoice_id" required><option value="">Choose invoice</option><?php foreach($invoices as $i):?><option value="<?=(int)$i['id']?>"><?=htmlspecialchars($i['invoice_number'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Amount <input name="amount" inputmode="decimal" required></label></p><p><button>Apply credit</button> <a href="/Tuman/teacher/credits.php">Cancel</a></p></form><?php tuman_teacher_page_end();?>
